begin;

-- Public booking: a private link lets the client view and cancel one publicly booked appointment, without an account.
-- The link carries a random 256-bit token generated by the browser; only its SHA-256 digest is stored here and the
-- token itself never reaches the database. The digest is attached in the same transaction as the booking. Phone
-- number, appointment id and idempotency key never grant access.
-- Additive only: existing functions and tables are unchanged, so code that still calls create_public_booking_atomic
-- keeps working while this migration is live and the new code is not deployed yet. No links are created for
-- appointments booked before this migration.

create table public.public_booking_manage_tokens (
  appointment_id uuid primary key references public.appointments(id) on delete cascade,
  token_hash bytea not null unique,
  created_at timestamptz not null default pg_catalog.now(),
  constraint public_booking_manage_tokens_hash_length check (pg_catalog.octet_length(token_hash) = 32)
);

alter table public.public_booking_manage_tokens enable row level security;
revoke all on table public.public_booking_manage_tokens from public, anon, authenticated, service_role;

create or replace function public.parse_public_booking_manage_token_hash_v1(p_token_hash text)
returns bytea
language sql
immutable
set search_path = ''
as $$
  select case when p_token_hash ~ '^[0-9a-f]{64}$' then pg_catalog.decode(p_token_hash, 'hex') end
$$;

revoke all on function public.parse_public_booking_manage_token_hash_v1(text) from public, anon, authenticated, service_role;

-- Books through the existing gated wrapper (replay, access, per-employee lock, phone, limit) and attaches the link
-- digest in the same transaction. A replay with the same key and the same digest returns manage_access=true again;
-- the digest is never replaced. A replay with another digest is refused and writes nothing. An appointment that was
-- booked without a link (before 056 or by an older client) stays without one.
create or replace function public.create_public_booking_with_manage_token_v1(
  p_salon_slug text,
  p_service_id uuid,
  p_employee_id uuid,
  p_start_time timestamptz,
  p_customer_full_name text,
  p_customer_phone text,
  p_customer_email text,
  p_idempotency_key uuid,
  p_manage_token_hash text
)
returns table (
  appointment_id uuid,
  was_created boolean,
  booked_service_name text,
  appointment_start timestamptz,
  manage_access boolean
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_hash bytea := public.parse_public_booking_manage_token_hash_v1(p_manage_token_hash);
  v_booking record;
  v_existing_hash bytea;
begin
  if v_hash is null then
    raise exception 'A valid manage token digest is required.' using errcode = '22023';
  end if;

  select booking.* into v_booking
  from public.create_public_booking_atomic(
    p_salon_slug, p_service_id, p_employee_id, p_start_time,
    p_customer_full_name, p_customer_phone, p_customer_email, p_idempotency_key
  ) booking;

  if v_booking.was_created then
    insert into public.public_booking_manage_tokens (appointment_id, token_hash)
    values (v_booking.appointment_id, v_hash);
    return query select v_booking.appointment_id, true, v_booking.booked_service_name, v_booking.appointment_start, true;
    return;
  end if;

  select token.token_hash into v_existing_hash
  from public.public_booking_manage_tokens token
  where token.appointment_id = v_booking.appointment_id;

  if v_existing_hash is not null and v_existing_hash <> v_hash then
    raise exception using errcode = 'P0001', message = 'IDEMPOTENCY_CONFLICT';
  end if;

  return query select v_booking.appointment_id, false, v_booking.booked_service_name, v_booking.appointment_start,
    v_existing_hash is not null;
end;
$$;

-- Used by the route when it answers a replay itself: 'match', 'absent' (booked without a link) or 'mismatch'.
create or replace function public.get_public_booking_manage_token_state_v1(p_appointment_id uuid, p_token_hash text)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when token.token_hash is null then 'absent'
    when token.token_hash = public.parse_public_booking_manage_token_hash_v1(p_token_hash) then 'match'
    else 'mismatch'
  end
  from (select 1) one
  left join public.public_booking_manage_tokens token on token.appointment_id = p_appointment_id
$$;

-- Read-only view of one appointment by its link digest. Returns no client data (name, phone, email or card).
-- No row for an unknown digest, so an invalid link cannot tell whether an appointment exists.
create or replace function public.get_public_booking_by_manage_token_v1(p_token_hash text)
returns table (
  salon_name text,
  salon_slug text,
  salon_phone text,
  salon_timezone text,
  service_name text,
  start_time timestamptz,
  end_time timestamptz,
  status text,
  can_cancel boolean,
  cancel_deadline timestamptz
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    salon.name,
    salon.slug,
    salon.phone,
    coalesce(salon.timezone, 'Europe/Belgrade'),
    coalesce(snapshot.service_name_snapshot, service.name),
    appointment.start_time,
    appointment.end_time,
    appointment.status::text,
    appointment.status in ('pending', 'confirmed')
      and pg_catalog.now() <= appointment.start_time - interval '2 hours',
    appointment.start_time - interval '2 hours'
  from public.public_booking_manage_tokens token
  join public.appointments appointment
    on appointment.id = token.appointment_id
   and appointment.booking_source = 'public'
  join public.salons salon on salon.id = appointment.salon_id
  left join public.appointment_services snapshot
    on snapshot.appointment_id = appointment.id
   and snapshot.sort_order = 0
  left join public.services service on service.id = appointment.primary_service_id
  where token.token_hash = public.parse_public_booking_manage_token_hash_v1(p_token_hash)
$$;

-- Cancels one public pending/confirmed appointment by its link digest when at least 2 hours remain before it starts.
-- Billing access and the salon's booking switches are intentionally not checked: an existing appointment stays
-- cancellable within the deadline. The row is locked, so concurrent or repeated calls produce exactly one
-- 'cancelled' (with exactly one salon notification, written in the same transaction); the others get
-- 'already_cancelled'. The cancelled appointment no longer holds its slot, the online limit or a reminder.
-- Outcomes: cancelled, already_cancelled, too_late, not_cancellable, not_found.
create or replace function public.cancel_public_booking_by_manage_token_v1(p_token_hash text)
returns table (outcome text, salon_phone text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_appointment_id uuid;
  v_appointment public.appointments%rowtype;
  v_salon record;
  v_client_name text;
  v_service_name text;
begin
  select token.appointment_id into v_appointment_id
  from public.public_booking_manage_tokens token
  where token.token_hash = public.parse_public_booking_manage_token_hash_v1(p_token_hash);

  if v_appointment_id is null then
    return query select 'not_found'::text, null::text;
    return;
  end if;

  select appointment.* into v_appointment
  from public.appointments appointment
  where appointment.id = v_appointment_id
    and appointment.booking_source = 'public'
  for update;

  if not found then
    return query select 'not_found'::text, null::text;
    return;
  end if;

  select salon.phone, coalesce(salon.timezone, 'Europe/Belgrade') as timezone into v_salon
  from public.salons salon where salon.id = v_appointment.salon_id;

  if v_appointment.status = 'cancelled' then
    return query select 'already_cancelled'::text, v_salon.phone;
    return;
  end if;

  if v_appointment.status not in ('pending', 'confirmed') then
    return query select 'not_cancellable'::text, v_salon.phone;
    return;
  end if;

  if pg_catalog.now() > v_appointment.start_time - interval '2 hours' then
    return query select 'too_late'::text, v_salon.phone;
    return;
  end if;

  update public.appointments appointment
  set status = 'cancelled',
      cancelled_at = pg_catalog.now(),
      cancelled_by = 'public_manage_link'
  where appointment.id = v_appointment.id;

  select client.full_name into v_client_name from public.clients client where client.id = v_appointment.client_id;
  select coalesce(snapshot.service_name_snapshot, service.name) into v_service_name
  from public.appointments appointment
  left join public.appointment_services snapshot on snapshot.appointment_id = appointment.id and snapshot.sort_order = 0
  left join public.services service on service.id = appointment.primary_service_id
  where appointment.id = v_appointment.id;

  insert into public.notifications (salon_id, type, title, message, entity_type, entity_id)
  values (
    v_appointment.salon_id,
    'appointment_cancelled',
    'Termin otkazan',
    coalesce(v_client_name, 'Klijent') || ' je otkazao/la ' || coalesce(v_service_name, 'termin') || ' za '
      || pg_catalog.to_char(v_appointment.start_time at time zone v_salon.timezone, 'DD.MM.YYYY. HH24:MI')
      || ' preko linka za upravljanje terminom.',
    'appointment',
    v_appointment.id
  );

  return query select 'cancelled'::text, v_salon.phone;
end;
$$;

revoke all on function public.create_public_booking_with_manage_token_v1(text, uuid, uuid, timestamptz, text, text, text, uuid, text)
  from public, anon, authenticated;
revoke all on function public.get_public_booking_manage_token_state_v1(uuid, text) from public, anon, authenticated;
revoke all on function public.get_public_booking_by_manage_token_v1(text) from public, anon, authenticated;
revoke all on function public.cancel_public_booking_by_manage_token_v1(text) from public, anon, authenticated;
grant execute on function public.create_public_booking_with_manage_token_v1(text, uuid, uuid, timestamptz, text, text, text, uuid, text)
  to service_role;
grant execute on function public.get_public_booking_manage_token_state_v1(uuid, text) to service_role;
grant execute on function public.get_public_booking_by_manage_token_v1(text) to service_role;
grant execute on function public.cancel_public_booking_by_manage_token_v1(text) to service_role;

commit;
